function printPolicy(): void {
  const config = loadConfig();
  const policy = loadPolicy(config.projectRoot);
  console.log(`policy: ${policyPath(config.projectRoot)}`);
  console.log(`approval: ${policy.approval ?? "config default"}`);
  console.log(`providers: ${policy.allowedProviders?.join(", ") ?? "all configured providers"}`);
  console.log(`command allowlist: ${policy.allowedCommands?.join(" | ") ?? "not restricted"}`);
  console.log(`command denylist: ${policy.deniedCommands?.join(" | ") ?? "safety defaults only"}`);
}

function printConfig(): void {
  const config = loadConfig();
  console.log(`project: ${config.projectRoot}`);
  console.log(`provider: ${config.provider}`);
  console.log(`model: ${config.model || "not selected"}`);
  console.log(`cheap model: ${config.cheapModel || "not selected"}`);
  console.log(`strong model: ${config.strongModel || "not selected"}`);
  console.log(`routing: ${config.routing}`);
  console.log(`base URL: ${config.baseUrl || "provider default"}`);
  console.log(`approval: ${config.approval}`);
  console.log(`input budget: ${config.maxInputTokens.toLocaleString()} tokens`);
  console.log(`output budget: ${config.maxOutputTokens.toLocaleString()} tokens`);
  console.log(`tool-turn budget: ${config.maxToolTurns}`);
}

async function printContext(task: string): Promise<void> {
  const config = loadConfig();
  const selection = await selectContext(await inspectRepository(config.projectRoot), task, config.maxInputTokens);
  console.log(`context for: ${selection.task}`);
  console.log(`selected: ${selection.selected.length} files / ~${selection.estimatedTokens.toLocaleString()} tokens`);
  for (const file of selection.selected) console.log(`  + ${file.relativePath} (~${file.estimatedTokens} tokens; ${file.reason})`);
  if (selection.omitted.length) console.log(`omitted: ${selection.omitted.length} files (budget ${selection.budgetTokens.toLocaleString()} tokens)`);
}

async function printReplay(task: string, spec?: string): Promise<void> {
  const config = loadConfig();
  const context = await selectContext(await inspectRepository(config.projectRoot), task, config.maxInputTokens);
  const results = replayTask(config, context, createTaskPlan(task), parseReplayCandidates(spec, config));
  if (results.length === 0) throw new Error("No replay candidates configured. Use --models provider:model,provider:model.");
  console.log(`replay for: ${task}`);
  console.log(`shared context: ~${context.estimatedTokens.toLocaleString()} tokens across ${context.selected.length} files`);
  for (const result of results) console.log(`${result.rank}. ${result.provider}/${result.model} — ~${result.estimatedTotalTokens.toLocaleString()} tokens, $${result.estimatedCost.toFixed(6)}, ${result.estimatedSavingsPercent.toFixed(1)}% input savings`);
}

async function printBudget(task: string): Promise<void> {
  const config = loadConfig();
  const snapshot = await inspectRepository(config.projectRoot);
  const context = await selectContext(snapshot, task, config.maxInputTokens);
  const route = routeTask(task, config);
  const plan = createBudgetPlan(config, context, createTaskPlan(task), route);
  console.log(`budget for: ${plan.task}`);
  console.log(`provider/model: ${plan.provider}/${plan.model || "not selected"}`);
  console.log(`tier: ${plan.tier}`);
  console.log(`input: ~${plan.estimatedInputTokens.toLocaleString()} tokens (context ${plan.contextTokens.toLocaleString()})`);
  console.log(`output allowance: ~${plan.estimatedOutputTokens.toLocaleString()} tokens`);
  console.log(`tool turns: ${plan.estimatedToolTurns}`);
  console.log(`total allowance: ~${plan.estimatedTotalTokens.toLocaleString()} tokens`);
  console.log(`baseline input: ~${plan.baselineInputTokens.toLocaleString()} tokens`);
  console.log(`estimated savings: ${plan.estimatedSavingsPercent.toFixed(1)}%`);
  console.log(`estimated cost: $${plan.estimatedCost.toFixed(6)}`);
  for (const warning of plan.warnings) console.log(`warning: ${warning}`);
}

