async function printDoctor(): Promise<void> {
  const root = loadConfig().projectRoot;
  const issues = await scanProjectSecurity(root);
  console.log(`node: ${process.version}`);
  console.log(`project: ${root}`);
  if (issues.length === 0) { console.log("security: PASS (no likely secrets found)"); return; }
  console.log(`security: FAIL (${issues.length} issue${issues.length === 1 ? "" : "s"})`);
  for (const issue of issues) console.log(`  ${issue.file}:${issue.line} ${issue.message}`);
  process.exitCode = 1;
}

