async function printMemory(args: string[]): Promise<void> {
  const store = openMemoryStore(loadConfig().projectRoot);
  try {
    if (args[0] === "sync") {
      const direction = args[1];
      if (direction !== "push" && direction !== "pull") throw new Error("ind memory sync requires push or pull.");
      const url = args[2] || process.env.IND_SYNC_URL?.trim();
      const secret = process.env.IND_SYNC_KEY?.trim();
      if (!url) throw new Error("Memory sync URL required as an argument or IND_SYNC_URL.");
      if (!secret) throw new Error("Memory sync requires IND_SYNC_KEY; it is never written to project memory.");
      const root = loadConfig().projectRoot;
      if (direction === "push") { await pushEncryptedMemory(url, await store.read(), secret); console.log("encrypted memory pushed"); }
      else { await writeFile(join(root, "MEMORY.md"), await pullEncryptedMemory(url, secret), "utf8"); console.log("encrypted memory pulled"); }
      return;
    }
    if (args[0] === "add") {
      if (!args[1] || args.length < 3) throw new Error("ind memory add requires a category and note.");
      await store.remember(args[1], args.slice(2).join(" "));
      console.log("memory note saved");
      return;
    }
    console.log((await store.read()).trim());
  } finally { store.close(); }
}

