function main(argv: string[]): void {
  const [command, ...rest] = argv;
  if (!command || command === "--help" || command === "-h") {
    console.log(HELP);
    return;
  }
  if (command === "--version" || command === "-v") {
    console.log(`ind ${VERSION}`);
    return;
  }
  if (command === "policy") {
    printPolicy();
    return;
  }
  if (command === "config") {
    printConfig();
    return;
  }
  if (command === "providers") {
    console.log(providerSummary().join("\n"));
    return;
  }
  if (command === "replay") {
    if (rest.length === 0) throw new Error("ind replay requires a task description.");
    const flag = rest.indexOf("--models");
    const spec = flag >= 0 ? rest[flag + 1] : undefined;
    const taskParts = flag >= 0 ? rest.slice(0, flag) : rest;
    void printReplay(taskParts.join(" "), spec).catch((error) => { console.error(`IND replay error: ${error instanceof Error ? error.message : String(error)}`); process.exitCode = 1; });
    return;
  }
  if (command === "budget") {
    if (rest.length === 0) throw new Error("ind budget requires a task description.");
    void printBudget(rest.join(" ")).catch((error) => { console.error(`IND budget error: ${error instanceof Error ? error.message : String(error)}`); process.exitCode = 1; });
    return;
  }
  if (command === "route") {
    if (rest.length === 0) throw new Error("ind route requires a task description.");
    printRoute(rest.join(" "));
    return;
  }
  if (command === "events") {
    void printEvents().catch((error) => { console.error(`IND events error: ${error instanceof Error ? error.message : String(error)}`); process.exitCode = 1; });
    return;
  }
  if (command === "doctor") {
    void printDoctor().catch((error) => { console.error(`IND doctor error: ${error instanceof Error ? error.message : String(error)}`); process.exitCode = 1; });
    return;
  }
  if (command === "leaderboard") {
    void printLeaderboard().catch((error) => { console.error(`IND leaderboard error: ${error instanceof Error ? error.message : String(error)}`); process.exitCode = 1; });
    return;
  }
  if (command === "benchmark") {
    void printBenchmark().catch((error) => { console.error(`IND benchmark error: ${error instanceof Error ? error.message : String(error)}`); process.exitCode = 1; });
    return;
  }
  if (command === "discover") {
    void printDiscovery().catch((error) => { console.error(`IND discovery error: ${error instanceof Error ? error.message : String(error)}`); process.exitCode = 1; });
    return;
  }
  if (command === "memory") {
    void printMemory(rest).catch((error) => { console.error(`IND memory error: ${error instanceof Error ? error.message : String(error)}`); process.exitCode = 1; });
    return;
  }
  if (command === "resume") {
    const store = openMemoryStore(loadConfig().projectRoot);
    try { const state = store.getResume(); console.log(state ? `resume: ${state.task} ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â chunk ${state.currentChunk} ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ${state.status} ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â next: ${state.nextStep}` : "No saved IND session to resume."); } finally { store.close(); }
    return;
  }
  if (command === "usage") {
    printUsage();
    return;
  }
  if (command === "plan") {
    if (rest.length === 0) throw new Error("ind plan requires a task description.");
    printPlan(rest.join(" "));
    return;
  }
  if (command === "context") {
    if (rest.length === 0) throw new Error("ind context requires a task description.");
    void printContext(rest.join(" ")).catch((error) => {
      console.error(`IND context error: ${error instanceof Error ? error.message : String(error)}`);
      process.exitCode = 1;
    });
    return;
  }
  if (command === "run" && rest.length === 0) {
    throw new Error("ind run requires a task description.");
  }
  throw new Error(`Command '${command}' is not implemented yet. Run 'ind --help' for the planned commands.`);
}

try {
  main(process.argv.slice(2));
} catch (error) {
  console.error(`IND error: ${error instanceof Error ? error.message : String(error)}`);
  process.exitCode = 1;
}







